srun --jobid=3470 --overlap -w prime-nebius-puku-h200-gpu-055 bash -lc 'cd /home/garrett/github/PrimeIntellect-ai/prime-rl-feat-ds-v4-fp8-grouped-o-a-proj && CUDA_VISIBLE_DEVICES=0 uv run --no-sync python ~/.claude/skills/profiling/scripts/bench_ops.py ~/tmp/profiling/dsv4-fp8-o-a-proj/cases_o_a_proj.py --memory --csv ~/tmp/profiling/dsv4-fp8-o-a-proj/derived/o_a_proj_bench.csv'
